-- Procurement Intelligence Platform: Gold layer DDL (Databricks Delta / Unity Catalog)
-- Generated by src/build_deliverables.py from the prototype's Gold tables. PK/FK constraints are informational (RELY).
-- Bronze/Silver/Ops tables are created in notebooks 21-24 and 28.

CREATE TABLE IF NOT EXISTS gold.dim_project (
  project_id                     STRING NOT NULL COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  project_name                   STRING COMMENT 'Project name',
  approval_date                  DATE COMMENT 'Board approval date',
  closing_date                   DATE COMMENT 'Current closing date',
  status                         STRING COMMENT 'Active | Closed | Pipeline | Dropped',
  lending_instrument             STRING COMMENT 'IPF, PforR, DPF, ...',
  commitment_usd                 DOUBLE COMMENT 'Total commitment (USD)',
  env_category                   STRING COMMENT 'Environmental category A/B/C/F (older projects)',
  es_risk_rating                 STRING COMMENT 'Environmental & social risk rating (ESF projects; NULL before ESF)',
  major_sector                   STRING COMMENT 'Major sector of the project',
  implementing_agency            STRING COMMENT 'Implementing agency',
  project_url                    STRING COMMENT 'Project page',
  objective                      STRING COMMENT 'Project development objective',
  region                         STRING COMMENT 'World Bank region of the borrower country',
  state                          STRING COMMENT 'Sub-national state (India scope only)',
  n_tenders                      DOUBLE COMMENT 'Tenders observed for the project',
  median_cycle_days              DOUBLE COMMENT 'Median invitation-to-award days for the project''s tenders',
  CONSTRAINT pk_dim_project PRIMARY KEY (project_id) RELY
)
CLUSTER BY (project_id)
COMMENT 'one project. Source: Projects API'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.dim_supplier (
  supplier_key                   STRING NOT NULL COMMENT 'Resolved supplier: normalised name key + supplier country (after fuzzy merge)',
  supplier_name                  STRING COMMENT 'Supplier name as published',
  name_variants                  STRING COMMENT 'JSON list of all raw spellings merged into this supplier',
  n_contracts                    BIGINT COMMENT 'Contracts awarded to this supplier',
  total_usd                      DOUBLE COMMENT 'Total awarded value (USD)',
  supplier_country               STRING COMMENT 'Supplier country',
  CONSTRAINT pk_dim_supplier PRIMARY KEY (supplier_key) RELY
)
CLUSTER BY (supplier_key)
COMMENT 'one resolved supplier. Source: resolved from contract supplier names'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.country_governance_year (
  country_iso3                   STRING NOT NULL COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  year                           BIGINT NOT NULL COMMENT 'Calendar year of the indicator (forward-filled ≤ 3 years, never back-filled)',
  cpia_budget_financial_mgmt     DOUBLE COMMENT 'CPIA quality of budgetary and financial management (1-6)',
  cpia_public_sector_mgmt        DOUBLE COMMENT 'CPIA public sector management and institutions cluster (1-6)',
  cpia_transparency_corruption   DOUBLE COMMENT 'CPIA transparency, accountability and corruption (1-6)',
  wgi_control_of_corruption      DOUBLE COMMENT 'WGI control of corruption (about -2.5 to 2.5)',
  wgi_gov_effectiveness          DOUBLE COMMENT 'WGI government effectiveness',
  wgi_regulatory_quality         DOUBLE COMMENT 'WGI regulatory quality',
  cpia_missing                   BIGINT COMMENT '1 when CPIA is not published (non-IDA countries)',
  CONSTRAINT pk_country_governance_year PRIMARY KEY (country_iso3, year) RELY
)
COMMENT 'country × year. Source: WDI API: CPIA + WGI'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.notices (
  notice_id                      STRING NOT NULL COMMENT 'Procurement notice id (OP...)',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  notice_type                    STRING COMMENT 'Invitation for Bids, Request for Expression of Interest, Contract Award, ...',
  notice_date                    DATE COMMENT 'Publication date of the notice',
  deadline_date                  DATE COMMENT 'Bid / EOI submission deadline',
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  bid_ref                        STRING COMMENT 'Borrower bid reference as published',
  description                    STRING COMMENT 'Free-text description of the package / contract',
  procurement_category           STRING COMMENT 'Works | Goods | Consultant Services | Non-consulting Services',
  method_code                    STRING COMMENT 'Method code: RFB, RFQ, QCBS, CQS, INDV, DIR, ...',
  method_name                    STRING COMMENT 'Method as published on the notice',
  implementing_org               STRING COMMENT 'Implementing agency named on the notice',
  rebid_text                     BOOLEAN COMMENT 'Notice text indicates a re-tender / re-advertisement',
  award_date                     DATE COMMENT 'Earliest contract-award notice date',
  n_bidders                      DOUBLE COMMENT 'Number of bids / proposals received (award notice)',
  n_rejected                     DOUBLE COMMENT 'Number of bids rejected (award notice)',
  rejection_reasons              STRING COMMENT 'Reasons for rejection, as published',
  awarded_names                  STRING COMMENT 'Awarded firm(s) named on the award notice',
  contract_duration_months       DOUBLE COMMENT 'Contract duration on the award notice',
  notice_version                 DOUBLE COMMENT 'Amendment counter of the award notice',
  bid_ref_key                    STRING COMMENT 'Normalised bid reference; equals tender_id',
  CONSTRAINT pk_notices PRIMARY KEY (notice_id) RELY
)
CLUSTER BY (country_iso3, notice_date)
COMMENT 'one procurement notice. Source: Procurement Notices API'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.fact_tender (
  tender_id                      STRING NOT NULL COMMENT 'Normalised bid reference (upper-case, punctuation removed); the tender''s identity',
  open_date                      DATE COMMENT 'First invitation (IFB / REOI) date: start of the procurement cycle',
  deadline_date                  DATE COMMENT 'Bid / EOI submission deadline',
  n_invitations                  BIGINT COMMENT 'Number of invitation notices for the same bid reference (re-advertisements)',
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  procurement_category           STRING COMMENT 'Works | Goods | Consultant Services | Non-consulting Services',
  procurement_method             STRING COMMENT 'Full method name (Request for Bids, QCBS, ...)',
  method_code                    STRING COMMENT 'Method code: RFB, RFQ, QCBS, CQS, INDV, DIR, ...',
  description                    STRING COMMENT 'Free-text description of the package / contract',
  implementing_org               STRING COMMENT 'Implementing agency named on the notice',
  open_notice_type               STRING COMMENT 'Type of the opening notice',
  award_date                     DATE COMMENT 'Earliest contract-award notice date',
  n_bidders                      DOUBLE COMMENT 'Number of bids / proposals received (award notice)',
  n_rejected                     DOUBLE COMMENT 'Number of bids rejected (award notice)',
  rejection_reasons              STRING COMMENT 'Reasons for rejection, as published',
  awarded_names                  STRING COMMENT 'Awarded firm(s) named on the award notice',
  contract_duration_months       DOUBLE COMMENT 'Contract duration on the award notice',
  rebid_flag                     BOOLEAN COMMENT 'Target: re-tendered (re-advertised or flagged as re-tender)',
  award_amended_flag             BOOLEAN COMMENT 'Award notice was amended',
  award_observed                 BOOLEAN COMMENT 'An award notice exists (event observed)',
  observed_days                  DOUBLE COMMENT 'Days from open to award, or to the data cut if still open (survival time)',
  outcome_unknown                BOOLEAN COMMENT 'No award after 2 years: excluded as unknown outcome, not censored',
  cycle_days                     DOUBLE COMMENT 'Target: days from invitation to award (awarded tenders only)',
  bid_window_days                DOUBLE COMMENT 'Days between invitation and submission deadline',
  single_bid_flag                DOUBLE COMMENT 'Target: exactly one responsive bid',
  rejected_share                 DOUBLE COMMENT 'Share of bids rejected',
  tender_year                    DOUBLE COMMENT 'Year of invitation (joins governance by country + year)',
  review_type                    STRING COMMENT 'Prior | Post review by the Bank (''unknown'' when not published)',
  contract_usd                   DOUBLE COMMENT 'Awarded contract value (from the linked contract)',
  supplier_key                   STRING COMMENT 'Resolved supplier: normalised name key + supplier country (after fuzzy merge)',
  state_from                     STRING COMMENT 'Where the state came from: implementing agency or project',
  state                          STRING COMMENT 'Sub-national state (India scope only)',
  item_type                      STRING COMMENT 'What was bought, classified into the scope''s taxonomy (e.g. PCR, imaging, reagents, analyzers)',
  in_domain                      BOOLEAN COMMENT 'Item type belongs to the domain (laboratory and diagnostic equipment)',
  region                         STRING COMMENT 'World Bank region of the borrower country',
  CONSTRAINT pk_fact_tender PRIMARY KEY (tender_id) RELY,
  CONSTRAINT fk_fact_tender_project_id FOREIGN KEY (project_id) REFERENCES gold.dim_project
)
CLUSTER BY (country_iso3, tender_year)
COMMENT 'one tender (bid reference), from invitation to award. Source: built from notices'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.fact_contract (
  wb_contract_number             STRING NOT NULL COMMENT 'World Bank contract number',
  supplier_id                    STRING COMMENT 'WB supplier id (kept as evidence; not trusted alone)',
  supplier_name                  STRING COMMENT 'Supplier name as published',
  supplier_country               STRING COMMENT 'Supplier country',
  supplier_country_code          STRING COMMENT 'Supplier country ISO-2',
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  project_name                   STRING COMMENT 'Project name',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  region                         STRING COMMENT 'World Bank region of the borrower country',
  fiscal_year                    BIGINT COMMENT 'WB fiscal year of the award',
  signing_date                   DATE COMMENT 'Contract signing date',
  procurement_category           STRING COMMENT 'Works | Goods | Consultant Services | Non-consulting Services',
  procurement_method             STRING COMMENT 'Full method name (Request for Bids, QCBS, ...)',
  review_type                    STRING COMMENT 'Prior | Post review by the Bank (''unknown'' when not published)',
  amount_usd                     DOUBLE COMMENT 'Contract amount (USD)',
  description                    STRING COMMENT 'Free-text description of the package / contract',
  borrower_ref                   STRING COMMENT 'Borrower contract reference as published',
  borrower_ref_key               STRING COMMENT 'Normalised borrower reference (exact-key link to tender_id)',
  supplier_name_key              STRING COMMENT 'Normalised supplier name (legal forms, M/S, punctuation removed)',
  item_type                      STRING COMMENT 'What was bought, classified into the scope''s taxonomy (e.g. PCR, imaging, reagents, analyzers)',
  in_domain                      BOOLEAN COMMENT 'Item type belongs to the domain (laboratory and diagnostic equipment)',
  supplier_key                   STRING NOT NULL COMMENT 'Resolved supplier: normalised name key + supplier country (after fuzzy merge)',
  tender_id                      STRING COMMENT 'Normalised bid reference (upper-case, punctuation removed); the tender''s identity',
  tender_link_method             STRING COMMENT 'How the contract was linked to its tender: exact_key | fuzzy_desc',
  tender_link_confidence         DOUBLE COMMENT 'Confidence of the tender link (1.0 exact; similarity otherwise)',
  state                          STRING COMMENT 'Sub-national state (India scope only)',
  CONSTRAINT pk_fact_contract PRIMARY KEY (wb_contract_number, supplier_key) RELY,
  CONSTRAINT fk_fact_contract_tender_id FOREIGN KEY (tender_id) REFERENCES gold.fact_tender,
  CONSTRAINT fk_fact_contract_project_id FOREIGN KEY (project_id) REFERENCES gold.dim_project,
  CONSTRAINT fk_fact_contract_supplier_key FOREIGN KEY (supplier_key) REFERENCES gold.dim_supplier
)
CLUSTER BY (item_type, country_iso3)
COMMENT 'one contract-supplier row. Source: Major Contract Awards (FinancesOne)'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.proj_doc_chunks (
  chunk_id                       STRING NOT NULL COMMENT '<doc_id>_<sequence>; one section-bounded passage',
  doc_id                         STRING COMMENT 'Documents & Reports API id (also the PDF file name)',
  doc_type_code                  STRING COMMENT 'PAD | ISR | ICR | PPAR | PROC_PLAN',
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  doc_date                       STRING COMMENT 'Document date',
  title                          STRING COMMENT 'Document title (used in citations)',
  landing_url                    STRING COMMENT 'Document page on documents.worldbank.org (citation link)',
  section_path                   STRING COMMENT 'Heading path of the chunk (e.g. ''V. LESSONS > B. ...'')',
  section_kind                   STRING COMMENT 'lessons | key_factors | procurement_fiduciary | risk | ratings | results | design | annex | other',
  content_type                   STRING COMMENT 'narrative | table | annex',
  page_start                     BIGINT COMMENT 'First page of the passage (citation)',
  page_end                       BIGINT COMMENT 'Last page of the passage',
  n_words                        BIGINT COMMENT 'Words in the chunk (≤ 450, 60 overlap)',
  chunk_text                     STRING COMMENT 'Passage text, running headers removed',
  search_text                    STRING COMMENT 'Contextual text that is embedded: doc type | project | country | sector | date | section + text',
  CONSTRAINT pk_proj_doc_chunks PRIMARY KEY (chunk_id) RELY
)
CLUSTER BY (country_iso3, doc_type_code)
COMMENT 'section-bounded passage (≤ 450 words). Source: parsed PDFs'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.lessons (
  lesson_id                      STRING NOT NULL COMMENT '<doc_id>_L<n>',
  doc_id                         STRING COMMENT 'Documents & Reports API id (also the PDF file name)',
  chunk_id                       STRING COMMENT '<doc_id>_<sequence>; one section-bounded passage',
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  doc_type_code                  STRING COMMENT 'PAD | ISR | ICR | PPAR | PROC_PLAN',
  section_kind                   STRING COMMENT 'lessons | key_factors | procurement_fiduciary | risk | ratings | results | design | annex | other',
  paragraph                      DOUBLE COMMENT 'Numbered paragraph in the report',
  page_start                     BIGINT COMMENT 'First page of the passage (citation)',
  lesson                         STRING COMMENT 'Lesson statement (first sentence)',
  detail                         STRING COMMENT 'Full paragraph',
  procurement_stage              STRING COMMENT 'planning | tender_design | evaluation_award | contract_management | general',
  risk_category                  STRING COMMENT 'delay | capacity | fiduciary | safeguards | cost_overrun | specification | other',
  procurement_related            BOOLEAN COMMENT 'Lesson concerns procurement',
  evidence_quote                 STRING COMMENT 'Verbatim quote; must be found in the source chunk',
  extraction_method              STRING COMMENT 'rule_numbered_paragraph (local) | llm_extracted (Databricks)',
  quote_verified                 BOOLEAN COMMENT 'The quote was found verbatim in the source chunk (only verified lessons are served)',
  title                          STRING COMMENT 'Document title (used in citations)',
  landing_url                    STRING COMMENT 'Document page on documents.worldbank.org (citation link)',
  doc_date                       STRING COMMENT 'Document date',
  CONSTRAINT pk_lessons PRIMARY KEY (lesson_id) RELY,
  CONSTRAINT fk_lessons_chunk_id FOREIGN KEY (chunk_id) REFERENCES gold.proj_doc_chunks
)
CLUSTER BY (country_iso3, risk_category)
COMMENT 'one lesson learned. Source: Lessons / Key factors sections'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.rating_evidence (
  project_id                     STRING COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  dimension                      STRING COMMENT 'development_objective | implementation_progress',
  source_type                    STRING COMMENT 'ISR | ICR | ICRR | PPAR',
  date                           DATE COMMENT 'Date of the rating',
  rating                         STRING COMMENT 'Highly Satisfactory ... Highly Unsatisfactory',
  source_id                      STRING COMMENT '<doc_id>#ISR<n> etc.: the exact rating record',
  doc_id                         STRING COMMENT 'Documents & Reports API id (also the PDF file name)',
  via                            STRING COMMENT 'Where it was parsed from (e.g. ICR data sheet)'
)
COMMENT 'one dated DO / IP rating. Source: ICR data sheets, ISRs, PPARs'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.project_ratings_resolved (
  project_id                     STRING NOT NULL COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  dimension                      STRING NOT NULL COMMENT 'development_objective | implementation_progress',
  resolved_rating                STRING COMMENT 'Rating after the evidence hierarchy is applied',
  resolved_from                  STRING COMMENT 'Source type that won (PPAR > ICRR > ICR > latest ISR)',
  resolved_source_id             STRING COMMENT 'Record that won',
  conflict                       BOOLEAN COMMENT 'Sources fall on opposite sides of the satisfactory line',
  spread                         BIGINT COMMENT 'Rating steps between best and worst evidence',
  n_evidence                     BIGINT COMMENT 'Number of rating records',
  worst_isr                      STRING COMMENT 'Worst supervision rating during implementation',
  trajectory                     STRING COMMENT 'JSON list of (source, date, rating): kept so both sides can be cited',
  CONSTRAINT pk_project_ratings_resolved PRIMARY KEY (project_id, dimension) RELY,
  CONSTRAINT fk_project_ratings_resolved_project_id FOREIGN KEY (project_id) REFERENCES gold.dim_project
)
COMMENT 'project × rating dimension. Source: rating_evidence'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.project_outcomes (
  project_id                     STRING NOT NULL COMMENT 'World Bank project ID (P-code). The conformed key that joins structured and unstructured data',
  doc_id                         STRING COMMENT 'Documents & Reports API id (also the PDF file name)',
  restructurings                 BIGINT COMMENT 'Number of restructurings (ICR data sheet)',
  closing_planned                DATE COMMENT 'Original closing date',
  closing_actual                 DATE COMMENT 'Actual closing date',
  closing_extension_days         DOUBLE COMMENT 'Days the closing date was extended',
  outcome_rating                 STRING COMMENT 'Final outcome rating',
  bank_performance               STRING COMMENT 'Bank performance rating',
  me_quality                     STRING COMMENT 'Quality of monitoring and evaluation',
  n_isr_ratings                  BIGINT COMMENT 'ISR ratings found in the data sheet',
  CONSTRAINT pk_project_outcomes PRIMARY KEY (project_id) RELY
)
COMMENT 'one completed project. Source: ICR data sheet'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

