CREATE TABLE IF NOT EXISTS gold.tender_benchmarks (
  level                          STRING COMMENT 'Fallback level: country+category+method → category+method → category',
  country_iso3                   STRING COMMENT 'Country, ISO 3166 alpha-3 (ISO-2 and spelling variants resolved via alias table)',
  procurement_category           STRING COMMENT 'Works | Goods | Consultant Services | Non-consulting Services',
  method_code                    STRING COMMENT 'Method code: RFB, RFQ, QCBS, CQS, INDV, DIR, ...',
  n                              BIGINT COMMENT 'Tenders in the cohort (awarded + censored)',
  n_awarded                      BIGINT COMMENT 'Awarded tenders in the cohort',
  median_days                    DOUBLE COMMENT 'Kaplan-Meier median days to award (censoring-aware)',
  p80_days                       DOUBLE COMMENT 'Kaplan-Meier 80th percentile days to award (NULL when not reached)',
  naive_median_awarded_only      DOUBLE COMMENT 'Median when still-open tenders are ignored (shows the bias)',
  item_type                      STRING COMMENT 'What was bought, classified into the scope''s taxonomy (e.g. PCR, imaging, reagents, analyzers)'
)
COMMENT 'benchmark cohort. Source: Kaplan-Meier over fact_tender'
TBLPROPERTIES (delta.enableChangeDataFeed = true);

CREATE TABLE IF NOT EXISTS gold.kg_edges (
  src_type                       STRING COMMENT 'Source entity type',
  src_id                         STRING COMMENT 'Source entity id',
  rel                            STRING COMMENT 'Relationship',
  dst_type                       STRING COMMENT 'Target entity type',
  dst_id                         STRING COMMENT 'Target entity id',
  method                         STRING COMMENT 'exact_key | fuzzy_desc | fuzzy_name | temporal | llm_extracted | human_confirmed | rule_*',
  confidence                     DOUBLE COMMENT '0-1 confidence of the link'
)
CLUSTER BY (rel, dst_id)
COMMENT 'one typed link. Source: all of the above'
TBLPROPERTIES (delta.enableChangeDataFeed = true);
